from flask import Flask, request, jsonify, redirect, url_for, make_response, abort
app = Flask(__name__)
@app.errorhandler(404)
def not_found(error):
    return "Page not found", 404
@app.get("/missing")
def missing():
    abort(404)
if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8000)
